float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

// Türeve göre yumuşatılmış eşik (yalnız fragment'ta açılır): kenar net, tırtık yok.
#define AAW(x) max(abs(ddx(x)) + abs(ddy(x)), 0.0001)
#define AASTEP(edge, x) smoothstep((edge) - AAW(x), (edge) + AAW(x), (x))

code.fragment:
float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float2 p = i.uv - 0.5;
    float r = length(p) * 2.0;
    float th = atan2(p.y, p.x) * 57.29578;
    th = th + step(th, -90.0) * 360.0;
    // yay boyunca konum: 0 kuyruk (165°), 1 baş (15°); firca_hilal ile aynı yerleşim
    float s = (165.0 - th) / 150.0;
    float sc = saturate(s);
    // yay dışı sert kesilir (açı dikişinde türev patlar)
    float inArc = step(0.0, s) * step(s, 1.0);

    float w = _Width * pow(sc, 1.1) * (1.0 - smoothstep(0.82, 1.0, sc));
    float R0 = 0.94;

    float fib = vnoise(float2(r * _Fiber, sc * 2.0));
    float fib2 = vnoise(float2(r * _Fiber * 2.3 + 7.0, sc * 6.0));
    float clump = vnoise(float2(sc * 9.0, 3.0));
    float brush = fib * 0.65 + fib2 * 0.35;

    float rev = saturate(life / _Reveal);
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));

    // kenarlar yarıçap uzayında: köşelerde (w→0) türev patlamaz
    float innerK = (1.0 + (brush - 0.5) * 0.55 + (clump - 0.5) * 0.35) * (1.0 - e * 0.55);
    float outerR = R0 + _InkWidth * w;
    float innerR = R0 - innerK * w;
    float shp = (1.0 - AASTEP(outerR, r)) * AASTEP(innerR, r);
    shp *= inArc;
    shp *= 1.0 - AASTEP(rev * 1.04, s);
    shp *= AASTEP((1.0 - sc) * _Dry - 0.12, brush);
    shp *= AASTEP(e * 1.08, sc * 0.75 + brush * 0.25);

    float coreIn = 1.0 - AASTEP(R0, r);
    float bodyIn = 1.0 - AASTEP(R0 - (_CoreBand + (brush - 0.5) * 0.12) * w, r);
    float shadowIn = 1.0 - AASTEP(R0 - (_ShadowBand + (brush - 0.5) * 0.18) * w, r);
    float3 c = _InkColor.rgb;
    c = lerp(c, _CoreColor.rgb, coreIn);
    c = lerp(c, _BodyColor.rgb, bodyIn);
    c = lerp(c, _ShadowColor.rgb, shadowIn);
    c += _CoreColor.rgb * coreIn * (1.0 - bodyIn) * _Flash * (1.0 - saturate(life / 0.25));
    c *= i.color.rgb;
    return float4(c, shp);
}
